/// Spacing on the 4px grid (docs Foundations > Scale): s4 to s64. s10, s15, s22 and s30 are deprecated since 1.5.
abstract final class CmSpace {
  /// Icon to text inside small controls; badge and tag gaps.
  static const double s4 = 4;
  /// Default gap inside controls and between related items (buttons in a row, label to field).
  static const double s8 = 8;
  /// Control side padding; gap between list rows and small cards.
  static const double s12 = 12;
  /// Card padding on phones; gap between fields in a form.
  static const double s16 = 16;
  /// The default gap between cards (cm-stack, cm-grid); gap between form sections.
  static const double s20 = 20;
  /// Page padding (cm-page, cm-page-header); card padding (cm-card standard); gap between page sections (cm-layout).
  static const double s24 = 24;
  /// Gap between page sections.
  static const double s32 = 32;
  /// Large section spacing.
  static const double s40 = 40;
  /// Empty-state and hero spacing.
  static const double s48 = 48;
  /// Largest layout spacing.
  static const double s64 = 64;
  /// Deprecated since 1.5: off the 4px grid, kept with its old value for existing apps. Use space-8 (or space-12).
  @Deprecated('Deprecated since 1.5: off the 4px grid, kept with its old value for existing apps. Use space-8 (or space-12).')
  static const double s10 = 10;
  /// Deprecated since 1.5: off the 4px grid, kept with its old value for existing apps. Use space-16 (or space-12).
  @Deprecated('Deprecated since 1.5: off the 4px grid, kept with its old value for existing apps. Use space-16 (or space-12).')
  static const double s15 = 15;
  /// Deprecated since 1.5: off the 4px grid, kept with its old value for existing apps. Use space-24.
  @Deprecated('Deprecated since 1.5: off the 4px grid, kept with its old value for existing apps. Use space-24.')
  static const double s22 = 22;
  /// Deprecated since 1.5: off the 4px grid, kept with its old value for existing apps. Use space-32.
  @Deprecated('Deprecated since 1.5: off the 4px grid, kept with its old value for existing apps. Use space-32.')
  static const double s30 = 30;
}

/// Corner radii.
abstract final class CmRadius {
  /// Checkboxes and other small marks.
  static const double xs = 4;
  /// Controls: buttons, inputs, selects, badges, segmented controls, menu items.
  static const double sm = 6;
  /// Cards, popovers, dropdowns, menus, toasts.
  static const double md = 8;
  /// Panels, modals, side panels, bottom sheets.
  static const double lg = 12;
  /// Pills, avatars, toggles and circular icon buttons.
  static const double full = 9999;
}

/// Desktop type ramp.
abstract final class CmType {
  /// Marketing/hero only: the one big heading of a marketing-style page (the docs home). 40/48. Never in product UI.
  static const TextStyle displayLg = TextStyle(fontFamily: cmFontFamily, package: cmFontPackage, fontSize: 40, height: 1.2, fontWeight: FontWeight.w600);
  /// Large numbers and the rare marketing-style heading. 30/36.
  static const TextStyle display = TextStyle(fontFamily: cmFontFamily, package: cmFontPackage, fontSize: 30, height: 1.2, fontWeight: FontWeight.w600);
  /// Page titles (cm-page-header). 24/32 semibold.
  static const TextStyle headingLg = TextStyle(fontFamily: cmFontFamily, package: cmFontPackage, fontSize: 24, height: 1.3333333333333333, fontWeight: FontWeight.w600);
  /// Modal and side panel titles. 20/28.
  static const TextStyle headingMd = TextStyle(fontFamily: cmFontFamily, package: cmFontPackage, fontSize: 20, height: 1.4, fontWeight: FontWeight.w600);
  /// Section headings inside a page (a group of cards, a settings section). 18/26 semibold (owner standard, 1.6).
  static const TextStyle headingSection = TextStyle(fontFamily: cmFontFamily, package: cmFontPackage, fontSize: 18, height: 1.4444444444444444, fontWeight: FontWeight.w600);
  /// Card headings and form-group titles. 16/24 semibold.
  static const TextStyle headingSm = TextStyle(fontFamily: cmFontFamily, package: cmFontPackage, fontSize: 16, height: 1.5, fontWeight: FontWeight.w600);
  /// Long reading text. 16/24.
  static const TextStyle bodyLg = TextStyle(fontFamily: cmFontFamily, package: cmFontPackage, fontSize: 16, height: 1.5, fontWeight: FontWeight.w400);
  /// Default UI text: field values, buttons, list and table text. 14/20.
  static const TextStyle bodyMd = TextStyle(fontFamily: cmFontFamily, package: cmFontPackage, fontSize: 14, height: 1.4285714285714286, fontWeight: FontWeight.w400);
  /// Page descriptions, secondary lines, slim buttons, table cells. 13/18.
  static const TextStyle bodySm = TextStyle(fontFamily: cmFontFamily, package: cmFontPackage, fontSize: 13, height: 1.3846153846153846, fontWeight: FontWeight.w400);
  /// Supporting text: help text, hints, error messages, meta; captions, badges, counts, table headers. 12/16. Nothing is smaller.
  static const TextStyle bodyXs = TextStyle(fontFamily: cmFontFamily, package: cmFontPackage, fontSize: 12, height: 1.3333333333333333, fontWeight: FontWeight.w400);
  /// Form labels: fields, option groups, checkbox and radio group labels. 13/18 medium (owner standard, 1.6; was 14/20).
  static const TextStyle label = TextStyle(fontFamily: cmFontFamily, package: cmFontPackage, fontSize: 13, height: 1.3846153846153846, fontWeight: FontWeight.w500);
}

/// Responsive type ramp.
abstract final class CmTypeResponsive {
  /// Marketing/hero only, on phones. 30/36.
  static const TextStyle displayLg = TextStyle(fontFamily: cmFontFamily, package: cmFontPackage, fontSize: 30, height: 1.2, fontWeight: FontWeight.w600);
  /// Display text on phones.
  static const TextStyle display = TextStyle(fontFamily: cmFontFamily, package: cmFontPackage, fontSize: 24, height: 1.3333333333333333, fontWeight: FontWeight.w600);
  /// Page titles on phones.
  static const TextStyle headingLg = TextStyle(fontFamily: cmFontFamily, package: cmFontPackage, fontSize: 20, height: 1.4, fontWeight: FontWeight.w600);
  /// Modal and panel titles on phones.
  static const TextStyle headingMd = TextStyle(fontFamily: cmFontFamily, package: cmFontPackage, fontSize: 18, height: 1.4444444444444444, fontWeight: FontWeight.w600);
  /// Section titles on phones (same as desktop).
  static const TextStyle headingSm = TextStyle(fontFamily: cmFontFamily, package: cmFontPackage, fontSize: 16, height: 1.5, fontWeight: FontWeight.w600);
  /// Reading text on phones.
  static const TextStyle bodyLg = TextStyle(fontFamily: cmFontFamily, package: cmFontPackage, fontSize: 16, height: 1.5, fontWeight: FontWeight.w400);
