}

/// Shadows: only for things that float (menus, popovers, dialogs, toasts). Cards and panels are flat.
abstract final class CmShadow {
  /// Small overlays: tooltips, menus.
  static const List<BoxShadow> sm = [BoxShadow(offset: Offset(0, 1), blurRadius: 2, spreadRadius: 0, color: Color.fromRGBO(0, 0, 0, 0.06)), BoxShadow(offset: Offset(0, 1), blurRadius: 3, spreadRadius: 0, color: Color.fromRGBO(0, 0, 0, 0.08))];
  /// Popovers and dropdowns: select and combobox lists, date pickers, search results, notification panel.
  static const List<BoxShadow> md = [BoxShadow(offset: Offset(0, 4), blurRadius: 12, spreadRadius: 0, color: Color.fromRGBO(0, 0, 0, 0.08)), BoxShadow(offset: Offset(0, 2), blurRadius: 4, spreadRadius: 0, color: Color.fromRGBO(0, 0, 0, 0.04))];
  /// Modals, side panels, bottom sheets, toasts, save bars, dragged cards.
  static const List<BoxShadow> lg = [BoxShadow(offset: Offset(0, 16), blurRadius: 40, spreadRadius: 0, color: Color.fromRGBO(0, 0, 0, 0.14)), BoxShadow(offset: Offset(0, 4), blurRadius: 12, spreadRadius: 0, color: Color.fromRGBO(0, 0, 0, 0.06))];
  /// Deprecated since 1.5: use shadow-md (same value).
  @Deprecated('Deprecated since 1.5: use shadow-md (same value).')
  static const List<BoxShadow> s100 = [BoxShadow(offset: Offset(0, 4), blurRadius: 12, spreadRadius: 0, color: Color.fromRGBO(0, 0, 0, 0.08)), BoxShadow(offset: Offset(0, 2), blurRadius: 4, spreadRadius: 0, color: Color.fromRGBO(0, 0, 0, 0.04))];
}

/// Control heights (docs Foundations > Scale). On touch screens every control is at least [touch] tall.
abstract final class CmControlHeight {
  /// Small controls: toolbar and filter fields (size="small"), slim buttons, segmented controls.
  static const double sm = 32;
  /// Default height of buttons and icon buttons (36x36); segmented controls.
  static const double md = 36;
  /// Default height of form fields (text field, select, combobox, search, date pickers; since 1.6), large buttons, and every button on touch screens.
  static const double lg = 40;
  /// Form fields on touch screens (pointer: coarse); the minimum touch target of buttons (40px drawn, the hit area reaches 44px).
  static const double touch = 44;
}

/// Icon sizes.
abstract final class CmIconSize {
  /// Icons inside controls: buttons, fields, menu items.
  static const double sm = 16;
  /// Navigation icons.
  static const double md = 20;
  /// Feature icons: empty states, tiles.
  static const double lg = 24;
}

/// Motion: durations and the easing for every transition. Turn animations off when
/// `MediaQuery.disableAnimationsOf(context)` is true (see `cmDuration` in theme.dart).
abstract final class CmMotion {
  /// Hover, press, toggles, chevrons. 120ms.
  static const Duration fast = Duration(milliseconds: 120);
  /// Opening and closing: popovers, panels, accordions. 200ms.
  static const Duration base = Duration(milliseconds: 200);
  /// Every transition. Under prefers-reduced-motion components turn transitions off. cubic-bezier(0.2, 0, 0, 1).
  static const Cubic standard = Cubic(0.2, 0, 0, 1);
}
